using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart;

    public ShoppingCartTests()
    {
        _cart = new ShoppingCart();
    }

    // ──── AddItem ────

    [TestMethod]
    public void AddItem_SingleItem_AppearsInCart()
    {
        _cart.AddItem("SKU-001", 2, 9.99m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual((2, 9.99m), _cart.Items["SKU-001"]);
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("SKU-001", 1, 5.00m);
        _cart.AddItem("SKU-001", 3, 5.00m);

        Assert.HasCount(1, _cart.Items);
        Assert.AreEqual(4, _cart.Items["SKU-001"].Quantity);
    }

    [TestMethod]
    public void AddItem_DifferentSkus_AddsAll()
    {
        _cart.AddItem("A", 1, 10m);
        _cart.AddItem("B", 2, 20m);

        Assert.HasCount(2, _cart.Items);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_NullOrWhiteSpaceSku_Throws(string? sku)
    {
        Assert.ThrowsExactly<ArgumentException>(() => _cart.AddItem(sku!, 1, 1m));
    }

    [TestMethod]
    public void AddItem_ZeroQuantity_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU", 0, 1m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU", 1, -1m));
    }

    // ──── RemoveItem ────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-001", 1, 5m);

        _cart.RemoveItem("SKU-001");

        Assert.IsEmpty(_cart.Items);
    }

    [TestMethod]
    public void RemoveItem_NonexistentSku_ThrowsKeyNotFound()
    {
        Assert.ThrowsExactly<KeyNotFoundException>(
            () => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    public void RemoveItem_NullSku_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _cart.RemoveItem(null!));
    }

    // ──── CalculateTotal ────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_SingleItem_ReturnsQuantityTimesPrice()
    {
        _cart.AddItem("SKU", 3, 10m);

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfAll()
    {
        _cart.AddItem("A", 2, 5m);   // 10
        _cart.AddItem("B", 1, 20m);  // 20

        Assert.AreEqual(30m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterRemovingItem_ExcludesIt()
    {
        _cart.AddItem("A", 1, 100m);
        _cart.AddItem("B", 1, 50m);
        _cart.RemoveItem("B");

        Assert.AreEqual(100m, _cart.CalculateTotal());
    }

    // ──── ApplyCoupon ────

    [TestMethod]
    [DataRow("SAVE10", 10)]
    [DataRow("SAVE20", 20)]
    [DataRow("HALF",   50)]
    public void ApplyCoupon_ValidCode_ReducesTotal(string code, int discountPercent)
    {
        _cart.AddItem("SKU", 1, 100m);

        _cart.ApplyCoupon(code);

        var expected = 100m - (100m * discountPercent / 100m);
        Assert.AreEqual(expected, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Works()
    {
        _cart.AddItem("SKU", 1, 200m);

        _cart.ApplyCoupon("save10");

        Assert.AreEqual(180m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_Throws()
    {
        var ex = Assert.ThrowsExactly<ArgumentException>(
            () => _cart.ApplyCoupon("BOGUS"));

        Assert.Contains("BOGUS", ex.Message);
    }

    [TestMethod]
    public void ApplyCoupon_NullCode_Throws()
    {
        Assert.ThrowsExactly<ArgumentException>(
            () => _cart.ApplyCoupon(null!));
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedByNewCoupon_UsesLatest()
    {
        _cart.AddItem("SKU", 1, 100m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80m, _cart.CalculateTotal());
    }

    // ──── Integration / combined behavior ────

    [TestMethod]
    public void FullWorkflow_AddItemsApplyCouponRemoveItem_CorrectTotal()
    {
        _cart.AddItem("A", 2, 25m);   // 50
        _cart.AddItem("B", 1, 50m);   // 50
        _cart.ApplyCoupon("SAVE10");   // 10% off
        _cart.RemoveItem("B");         // leaves 50

        Assert.AreEqual(45m, _cart.CalculateTotal()); // 50 - 10% = 45
    }
}

